 1	// RUN: %dafny /verifyAllModules /allocated:1 /compile:0 /print:"%t.print" /dprint:"%t.dprint" "%s" > "%t"
 2	// RUN: %diff "%s.expect" "%t"
 3	
 4	// This test was contributed by Bryan. It has shown some instabilities in the past.
 5	
 6	method seqIntoArray<A>(s: seq<A>, a: array<A>, index: nat)
 7	  requires index + |s| <= a.Length
 8	  modifies a
 9	  ensures a[..] == old(a[..index]) + s + old(a[index + |s|..])
10	{
11	  var i := index;
12	
13	  while i < index + |s|
14	    invariant a[..] == old(a[..index]) + s[..i - index] + old(a[i..])
15	  {
16	    label A:
17	    a[i] := s[i - index];
18	    calc {
19	      a[..];
20	    ==  // assignment statement above
21	      old@A(a[..])[i := s[i - index]];
22	    ==  // invariant on entry to loop
23	      (old(a[..index]) + s[..i - index] + old(a[i..]))[i := s[i - index]];
24	    ==  { assert old(a[..index]) + s[..i - index] + old(a[i..]) == (old(a[..index]) + s[..i - index]) + old(a[i..]); }
25	      ((old(a[..index]) + s[..i - index]) + old(a[i..]))[i := s[i - index]];
26	    ==  { assert |old(a[..index]) + s[..i - index]| == i; }
27	      (old(a[..index]) + s[..i - index]) + old(a[i..])[0 := s[i - index]];
28	    == { assert old(a[i..])[0 := s[i - index]] == [s[i - index]] + old(a[i..])[1..]; }
29	      (old(a[..index]) + s[..i - index]) + [s[i - index]] + old(a[i..])[1..];
30	    ==  { assert old(a[i..])[1..] == old(a[i + 1..]); }
31	      (old(a[..index]) + s[..i - index]) + [s[i - index]] + old(a[i + 1..]);
32	    ==  // redistribute +
33	      old(a[..index]) + (s[..i - index] + [s[i - index]]) + old(a[i + 1..]);
34	    ==  { assert s[..i - index] + [s[i - index]] == s[..i + 1 - index]; }
35	      old(a[..index]) + s[..i + 1 - index] + old(a[i + 1..]);
36	    }
37	    i := i + 1;
38	  }
39	}
40

